SELECT "Uberlandia_1"."no_modalidade" AS "no_modalidade",   "Uberlandia_1"."nome_do_curso" AS "nome_do_curso",   SUM(CAST("Uberlandia_1"."Number_of_Records" AS BIGINT)) AS "sum_Number_of_Records_ok" FROM "Uberlandia_1" WHERE (("Uberlandia_1"."no_modalidade" = 'Pronatec Brasil sem Miséria') AND (NOT (("Uberlandia_1"."nome_da_sit_matricula__situacao_detalhada_" NOT IN ('', 'TRANSF_EXT', 'INTEGRALIZADA', 'FREQ_INIC_INSUF', 'TRANCADA', 'CONCLUÍDA', 'TRANSF_INT', 'EM_CURSO', 'REPROVADA', 'ABANDONO', 'CONFIRMADA', 'EM_DEPENDÊNCIA')) OR ("Uberlandia_1"."nome_da_sit_matricula__situacao_detalhada_" IS NULL))) AND (NOT ("Uberlandia_1"."situacao_da_turma" IN ('CANCELADA', 'CRIADA', 'PUBLICADA')))) GROUP BY "Uberlandia_1"."no_modalidade",   "Uberlandia_1"."nome_do_curso";
